import{_ as t}from"./chunks/board.DGfLJwTx.js";import{_ as a,o,c as d,a2 as s}from"./chunks/framework.DGOtNzMU.js";const g=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":1794936851000}'),r={name:"examples.md"};function i(n,e,c,l,h,p){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Three example apps live in the repository, from the smallest possible app to a full team board with sign in. They are separate Gradle builds that use ktor-svelte the way your project does, and they double as the end-to-end tests, so they always work with the current code.</p><table tabindex="0"><thead><tr><th>Example</th><th>Size</th><th>Best for</th></tr></thead><tbody><tr><td><a href="#basic">basic</a></td><td>One route, three pages</td><td>Seeing the minimum that works</td></tr><tr><td><a href="#notes">notes</a></td><td>A notes app</td><td>Each feature on its own, easy to find</td></tr><tr><td><a href="#showcase">showcase</a></td><td>A team board with users</td><td>Features working together in a real app</td></tr><tr><td><a href="#two-frontends">two-frontends</a></td><td>A public site and an admin area</td><td><a href="./guide/multiple-frontends">Multiple frontends</a> in one app</td></tr></tbody></table><h2 id="run-them" tabindex="-1">Run them <a class="header-anchor" href="#run-them" aria-label="Permalink to &quot;Run them&quot;">​</a></h2><p>Clone the repository, then start an example with everything in one command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/nijasc/ktor-svelte.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ktor-svelte</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/notes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><p>Open <code>http://localhost:8080</code>. In IntelliJ, open the repository and run the <code>Notes: Dev</code>, <code>Showcase: Dev</code> or <code>Basic: Dev</code> run configuration instead. You need Java 17 or newer and <a href="https://bun.sh" target="_blank" rel="noreferrer">Bun</a>.</p><p>To build and run the production JAR:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/notes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buildFatJar</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/notes/build/libs/notes-all.jar</span></span></code></pre></div><p>The showcase builds the same way with <code>buildFatJar</code>. The basic example uses Shadow instead, so its task is <code>shadowJar</code>.</p><h2 id="basic" tabindex="-1">basic <a class="header-anchor" href="#basic" aria-label="Permalink to &quot;basic&quot;">​</a></h2><p><a href="https://github.com/nijasc/ktor-svelte/tree/main/examples/basic" target="_blank" rel="noreferrer"><code>examples/basic</code></a> is the smallest possible app: <code>install(Svelte)</code> with no settings, one API route and three pages.</p><table tabindex="0"><thead><tr><th>Look at</th><th>To see</th></tr></thead><tbody><tr><td><code>src/main/kotlin/Application.kt</code></td><td><code>install(Svelte)</code> with no settings, and one API route</td></tr><tr><td><code>frontend/src/routes/+page.svelte</code>, <code>about/</code></td><td>Prerendered pages</td></tr><tr><td><code>frontend/src/routes/app/</code></td><td>A page that renders in the browser and calls the API</td></tr><tr><td><code>frontend/vite.config.ts</code></td><td>The <code>adapter-static</code> setup SvelteKit needs</td></tr></tbody></table><p>Start here when you want to see what ktor-svelte does before any of its options.</p><h2 id="notes" tabindex="-1">notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;notes&quot;">​</a></h2><p><a href="https://github.com/nijasc/ktor-svelte/tree/main/examples/notes" target="_blank" rel="noreferrer"><code>examples/notes</code></a> is a small notes app that uses almost every feature, each in a place that is easy to find. The <a href="./guide/tutorial">tutorial</a> builds a smaller version of it step by step.</p><table tabindex="0"><thead><tr><th>Look at</th><th>To see</th></tr></thead><tbody><tr><td><code>src/main/kotlin/notes/Application.kt</code></td><td><code>generateTs</code>, <code>transport { json(); xml(); compression() }</code>, <code>publicConfig</code> and <code>apiDocs</code></td></tr><tr><td><code>src/main/kotlin/notes/Model.kt</code></td><td>DTOs with <code>@JsonSchema</code> bounds and <code>Validated</code> rules, a query class, a sealed <code>Activity</code> and <code>Page&lt;Note&gt;</code></td></tr><tr><td><code>src/main/kotlin/notes/Routes.kt</code></td><td>CRUD routes with <code>resource</code>, typed 404 errors, a paged feed with <code>getPage</code> and multipart attachments</td></tr><tr><td><code>build.gradle.kts</code></td><td>Tailwind, DaisyUI with a custom theme, Lucide, typed routes, images, toasts and i18n, all in <code>svelte { libraries { } }</code></td></tr><tr><td><code>frontend/src/lib/api/</code></td><td>The generated client, committed</td></tr><tr><td><code>frontend/src/routes/notes/+page.svelte</code></td><td>Forms with <code>use:field</code>, client and server validation, search and tag filters</td></tr><tr><td><code>frontend/src/routes/notes/[id]/</code></td><td>A dynamic route with <code>apiWith(event)</code> in <code>load</code> and typed errors</td></tr><tr><td><code>frontend/src/routes/+layout.svelte</code></td><td>DaisyUI themes, Lucide icons and i18n with a language switcher</td></tr><tr><td><code>src/e2eTest/kotlin/NotesAppTest.kt</code></td><td>How the production JAR is tested end to end</td></tr></tbody></table><h3 id="things-to-try" tabindex="-1">Things to try <a class="header-anchor" href="#things-to-try" aria-label="Permalink to &quot;Things to try&quot;">​</a></h3><p>While <code>svelteDevAll</code> runs:</p><ul><li>Change a Svelte file: the page updates without a reload.</li><li>Add a property to <code>Note</code> in <code>Model.kt</code>: the app restarts, and <code>frontend/src/lib/api/types.ts</code> gains the property a moment later.</li><li>Open <code>http://localhost:8080/api/docs</code> for Swagger UI.</li><li>Submit an empty title: the error comes from the generated <code>validate()</code> before any request is sent.</li><li>Click the <strong>API</strong> button in the corner of a page to see every call, with its status and time.</li></ul><h2 id="showcase" tabindex="-1">showcase <a class="header-anchor" href="#showcase" aria-label="Permalink to &quot;showcase&quot;">​</a></h2><p><a href="https://github.com/nijasc/ktor-svelte/tree/main/examples/showcase" target="_blank" rel="noreferrer"><code>examples/showcase</code></a> is a team board that people sign in to. Where notes shows each feature on its own, the showcase shows them working together the way a real app needs them: pages behind a login, an admin area, a database and uploads.</p><p><img src="`+t+'" alt="The board of the showcase, with counters, a search box, filters and a list of tasks"></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/showcase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><h3 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h3><p>The first start creates two people, <code>ada@example.com</code> as admin and <code>grace@example.com</code> as member. Set their passwords with <code>SHOWCASE_ADMIN_PASSWORD</code> and <code>SHOWCASE_MEMBER_PASSWORD</code>, at least 10 characters each. Without them, the app generates passwords and writes them to its log once.</p><p>The data lives in <code>examples/showcase/build/showcase-data</code>, so <code>./gradlew -p examples/showcase clean</code> starts over.</p><h3 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Look at</th><th>To see</th></tr></thead><tbody><tr><td><code>src/main/kotlin/showcase/Application.kt</code></td><td><code>routing = SvelteRouting.Manual</code> with public pages, everything else behind <code>authenticate</code>, a named rate limit and a health check that asks the database</td></tr><tr><td><code>src/main/kotlin/showcase/Application.kt</code></td><td>Environment variables declared once with <code>environment</code>, and <code>startupStep</code> for the slow parts of startup</td></tr><tr><td><code>src/main/kotlin/showcase/Application.kt</code></td><td><code>currentUser&lt;User&gt;</code>, <code>loginPage</code>, <code>permissions</code>, <code>preferences</code> and page <code>guards</code>, declared once for both sides</td></tr><tr><td><code>src/main/kotlin/showcase/Application.kt</code></td><td><code>constants</code>, <code>errorCodes</code>, <code>idempotency()</code>, <code>frontendErrors()</code>, <code>webVitals</code> and a typed cookie</td></tr><tr><td><code>src/main/kotlin/showcase/Auth.kt</code></td><td>A signed session cookie, sign in, registration, and an admin area guarded on the server</td></tr><tr><td><code>src/main/kotlin/showcase/Database.kt</code>, <code>src/main/resources/db/migration/</code></td><td>Exposed on an embedded H2 database, with Flyway migrations</td></tr><tr><td><code>src/main/kotlin/showcase/TaskRoutes.kt</code></td><td>Paged and filtered lists, typed errors in the language of the person, multipart uploads with a size and type check, and downloads that browsers never run as a page</td></tr><tr><td><code>src/main/kotlin/showcase/Model.kt</code></td><td><code>@JsonSchema</code> bounds, <code>Validated</code> rules and a sealed <code>Activity</code> that becomes a TypeScript union</td></tr><tr><td><code>build.gradle.kts</code></td><td>Every frontend library at once: themes with a custom one, fonts, charts, an installable app, components, toasts with a reload prompt and i18n</td></tr><tr><td><code>frontend/src/routes/+layout.svelte</code></td><td>The generated <code>currentUser</code> store that the header reads</td></tr><tr><td><code>frontend/src/routes/(app)/+layout.ts</code></td><td>A layout group for the pages that need a session</td></tr><tr><td><code>frontend/src/routes/(app)/board/+page.svelte</code></td><td>Search as you type with <code>latest</code>, filters, &quot;load more&quot; with a cursor, and <code>prefetchOnHover</code></td></tr><tr><td><code>frontend/src/routes/(app)/tasks/[id]/+page.svelte</code></td><td>Uploads with a progress bar, comments, <code>Activity.match</code> and a confirm dialog</td></tr><tr><td><code>frontend/src/lib/components/TaskForm.svelte</code></td><td>One form for creating and editing, with <code>use:field</code> and errors from the browser and the server</td></tr><tr><td><code>frontend/messages/</code></td><td>English and German texts that the pages and the API errors share</td></tr><tr><td><code>frontend/src/emails/Welcome.svelte</code></td><td>A welcome email in English and German with a shared layout, rendered on registration and shown to admins at <code>/api/admin/emails/welcome</code></td></tr><tr><td><code>src/e2eTest/kotlin/ShowcaseAppTest.kt</code></td><td>Sessions, roles, uploads, paging and rate limits tested against the production JAR</td></tr><tr><td><code>src/browserTest/kotlin/ShowcaseBrowserTest.kt</code></td><td>The same JAR driven by Playwright in Chromium, Firefox and WebKit, with accessibility checks</td></tr><tr><td><code>src/devBrowserTest/kotlin/DevModeBrowserTest.kt</code></td><td><code>svelteDevAll</code> with a browser: hot reload, a restart after a Kotlin change, and browser errors in the dev log</td></tr></tbody></table><h3 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>The port the server listens on, 8080 unless you set it</td></tr><tr><td><code>SESSION_SIGN_KEY</code></td><td>64 hex characters that sign the session cookie, so sessions survive a restart</td></tr><tr><td><code>SHOWCASE_DATA</code></td><td>Where the database and the uploaded files go</td></tr><tr><td><code>SHOWCASE_REGISTRATION</code></td><td><code>closed</code> stops new people from creating an account</td></tr><tr><td><code>SHOWCASE_LOGIN_ATTEMPTS</code></td><td>Sign-in attempts allowed per minute, 10 unless you set it</td></tr><tr><td><code>SHOWCASE_SESSION_SECONDS</code></td><td>How long someone stays signed in, a week unless you set it</td></tr><tr><td><code>SHOWCASE_SITE_URL</code></td><td>The public address of the site, for the sitemap</td></tr><tr><td><code>SHOWCASE_INSECURE_COOKIES</code></td><td><code>true</code> to test the JAR over plain HTTP in browsers that do not treat <code>localhost</code> as secure</td></tr><tr><td><code>APP_NAME</code></td><td>The name shown in the header</td></tr></tbody></table><p>The pictures on the <a href="./">start page</a> come from <code>./gradlew -p examples/showcase screenshots</code>, which starts the showcase JAR in a headless Chromium.</p><h2 id="your-own-examples" tabindex="-1">Your own examples <a class="header-anchor" href="#your-own-examples" aria-label="Permalink to &quot;Your own examples&quot;">​</a></h2><p>The <a href="./recipes/">recipes</a> show complete solutions for sessions, uploads, live updates, paging and an admin area that you can copy into your app. <a href="./features/">Everything ktor-svelte does</a> links every feature to its page.</p><h2 id="two-frontends" tabindex="-1">two-frontends <a class="header-anchor" href="#two-frontends" aria-label="Permalink to &quot;two-frontends&quot;">​</a></h2><p>Two SvelteKit projects in one app: the public site in <code>frontend/</code> and an admin area in <code>admin/</code>, served under <code>/admin</code>.</p><table tabindex="0"><thead><tr><th>Look at</th><th>To see</th></tr></thead><tbody><tr><td><code>src/main/kotlin/twofrontends/Application.kt</code></td><td><code>frontend(&quot;/admin&quot;)</code> and <code>generateTs</code> with one API route</td></tr><tr><td><code>build.gradle.kts</code></td><td><code>svelte { frontend(&quot;admin&quot;) { } }</code>, and ports you can change with <code>-PvitePort</code>, <code>-PadminVitePort</code> and <code>-PdebugPort</code></td></tr><tr><td><code>admin/vite.config.ts</code></td><td><code>paths: { base: &#39;/admin&#39; }</code> and the admin&#39;s own hot reload port</td></tr><tr><td><code>frontend/src/lib/api/</code>, <code>admin/src/lib/api/</code></td><td>The same generated client in both frontends</td></tr><tr><td><code>src/browserTest/</code></td><td>Both frontends in a browser, from the packaged JAR</td></tr><tr><td><code>src/devBrowserTest/</code></td><td><code>svelteDevAll</code> with one Vite per frontend</td></tr></tbody></table>',38)])])}const b=a(r,[["render",i]]);export{g as __pageData,b as default};
